def backfill_status_logs(apps, schema_editor):
    """Give pre-existing bookings a timeline from the timestamps they already carry."""
    Booking = apps.get_model('bookings', 'Booking')
    Log = apps.get_model('bookings', 'BookingStatusLog')
    for b in Booking.objects.all().iterator():
        points = [('', 'AWAITING_ADVANCE_PAYMENT', b.created_at)]
        if b.confirmed_at:
            points.append(('AWAITING_PARTNER_CONFIRMATION', 'CONFIRMED', b.confirmed_at))
        if b.booking_status not in {p[1] for p in points}:
            points.append((points[-1][1], b.booking_status, b.cancellation_time or b.completed_at or b.updated_at))
        for frm, to, at in points:
            log = Log.objects.create(booking_id=b.pk, from_status=frm, to_status=to, actor_role='SYSTEM',
                                     notes='', metadata={'backfilled': True})
            Log.objects.filter(pk=log.pk).update(created_at=at or b.created_at)
        Booking.objects.filter(pk=b.pk).update(status_changed_at=points[-1][2])


def remove_backfilled(apps, schema_editor):
    apps.get_model('bookings', 'BookingStatusLog').objects.filter(metadata__backfilled=True).delete()


